using Aict.Core;
using Aict.Beta;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class BlockExplanationTests {
    [TestMethod] public void ExplainsEveryActiveConditionAndTheActualQuotaSlot(){var now=Samples.At(2,9,1);var slot=new QuotaSlot(Guid.NewGuid(),540,720,TimeSpan.FromMinutes(20),"上午");var g=Samples.Quota() with{DailyQuota=null,QuotaSlots=[slot],AlwaysBlock=true,Windows=[new(Weekdays.All,540,600)],Cycle=new(Samples.At(2,9),TimeSpan.FromMinutes(2),TimeSpan.FromMinutes(1)),BlockUntilUtc=Samples.At(2,9,30)};var p=Samples.Policy(g);var l=new UsageLedger().Put(g.Id,new(2026,11,2),new(TimeSpan.FromMinutes(20).Ticks),slot.Id);var lines=BlockExplanations.Describe(p,g,l,new(now,true));Assert.AreEqual(5,lines.Length);StringAssert.Contains(string.Join('\n',lines),"每周硬封锁时段：09:00—10:00");StringAssert.Contains(string.Join('\n',lines),"上午");StringAssert.Contains(string.Join('\n',lines),"20 分钟额度已用完");StringAssert.Contains(string.Join('\n',lines),"11-02 12:00:00");}
    [TestMethod] public void DetailTextDoesNotChangePlanFingerprintEverySecond(){var now=Samples.At(2,9,1);var g=Samples.Quota() with{AlwaysBlock=true,Cycle=new(Samples.At(2,9),TimeSpan.FromMinutes(2),TimeSpan.FromMinutes(1)),BlockUntilUtc=Samples.At(2,9,30)};var s=new EngineSnapshot{Policy=Samples.Policy(g),Clock=new(now,true)};var a=Plans.Web(s,true);var b=Plans.Web(s with{Clock=new(now.AddSeconds(1),true)},true);Assert.AreEqual(a.Fingerprint,b.Fingerprint);Assert.AreEqual(g.Name,a.Groups[0].Name);Assert.IsTrue(a.Groups[0].Details!.Value.Any(x=>x.Contains("本轮至")));}
    [TestMethod] public void IncompleteUsageAndClockProblemsAreDistinguishedFromQuotaExhaustion(){var g=Samples.Quota();var p=Samples.Policy(g);var l=new UsageLedger().Put(g.Id,new(2026,11,2),new(0,true));var lines=string.Join('\n',BlockExplanations.Describe(p,g,l,new(Samples.At(2,10),false),false));StringAssert.Contains(lines,"时间校验异常");StringAssert.Contains(lines,"使用记录不完整");Assert.IsFalse(lines.Contains("额度已用完"));}
    [TestMethod] public void InactiveWindowHasNoMisleadingQuotaReason(){var g=Samples.Quota() with{DailyQuotaWindow=new(540,720)};var p=Samples.Policy(g);var l=new UsageLedger().Put(g.Id,new(2026,11,2),new(TimeSpan.FromHours(1).Ticks));Assert.IsTrue(BlockExplanations.Describe(p,g,l,new(Samples.At(2,18),true),true).IsEmpty);}
}
